"use client";

import { useMemo, type ReactNode } from "react";
import { QueryClient, QueryClientProvider, useQueryClient } from "@tanstack/react-query";
import {
  DataGridProvider,
  DataGridRoot,
  DataGridHeader,
  DataGridBody,
  defineColumns,
} from "@/registry/default/components/data-grid/data-grid";
import { useDataGridServerRows, type ServerRowsRequest } from "@/registry/default/components/data-grid-server/data-grid-server";

const TOTAL_COUNT = 10_000;
const SIMULATED_LATENCY_MS = 300;

type LazyRow = { id: string; name: string; email: string; score: number };

/** Deterministic per-index row, so the same server index always resolves to the same content. */
function rowAt(index: number): LazyRow {
  return {
    id: `row-${index}`,
    name: `Person ${index}`,
    email: `person${index}@example.com`,
    score: (index * 37) % 100,
  };
}

function createSimulatedApi() {
  return {
    async fetchRows({ start, end, signal }: Pick<ServerRowsRequest, "start" | "end" | "signal">): Promise<LazyRow[]> {
      await new Promise((resolve, reject) => {
        const timer = setTimeout(resolve, SIMULATED_LATENCY_MS);
        signal.addEventListener("abort", () => {
          clearTimeout(timer);
          reject(new DOMException("aborted", "AbortError"));
        });
      });
      const rows: LazyRow[] = [];
      for (let i = start; i < end; i++) rows.push(rowAt(i));
      return rows;
    },
  };
}

const columns = defineColumns<LazyRow>()([
  { id: "id", header: "ID", accessorKey: "id", type: "text", width: 60, flex: 1, readOnly: true },
  { id: "name", header: "Name", accessorKey: "name", type: "text", width: 100, flex: 2 },
  { id: "email", header: "Email", accessorKey: "email", type: "text", width: 120, flex: 2 },
  { id: "score", header: "Score", accessorKey: "score", type: "number", width: 60, flex: 1 },
] as const);

/**
 * 10,000 rows through a TanStack Query cache: `useDataGridServerRows` in scroll mode hands each newly scrolled
 * block to `queryClient.fetchQuery`, which dedupes concurrent windows. With `staleTime: Infinity`, a cached
 * window never goes stale; nothing observes it, so the cache drops it after `gcTime` (5 minutes by
 * default). `queryFn` takes the query's own signal, not the request `signal`: a block the hook
 * aborts still finishes and fills the cache.
 */
function LazyReactQueryGrid(): ReactNode {
  const api = useMemo(() => createSimulatedApi(), []);
  const queryClient = useQueryClient();
  const server = useDataGridServerRows<LazyRow>({
    mode: "scroll",
    fetchRows: async ({ start, end }) => ({
      rows: await queryClient.fetchQuery({
        queryKey: ["rows", start, end],
        staleTime: Infinity,
        queryFn: ({ signal }) => api.fetchRows({ start, end, signal }),
      }),
      totalRowCount: TOTAL_COUNT,
    }),
  });
  const cachedWindows = queryClient.getQueriesData({ queryKey: ["rows"] }).length;

  return (
    <div className="w-full flex flex-col gap-2">
      <div className="flex items-center justify-between text-sm text-muted-foreground">
        <span>
          {(TOTAL_COUNT - server.unloadedCount).toLocaleString("en-US")} / {TOTAL_COUNT.toLocaleString("en-US")} rows loaded
          <span className={server.loading ? undefined : "invisible"}> · fetching…</span>
        </span>
        <span>{cachedWindows} windows in the query cache</span>
      </div>
      <div className="h-[420px] overflow-hidden rounded-md border border-border">
        <DataGridProvider {...server.providerProps} columns={columns}>
          <DataGridRoot className="h-full rounded-none border-none" {...server.rootProps}>
            <DataGridHeader />
            <DataGridBody />
          </DataGridRoot>
        </DataGridProvider>
      </div>
    </div>
  );
}

export default function DataGridLazyReactQueryDemo(): ReactNode {
  const queryClient = useMemo(() => new QueryClient(), []);
  return (
    <QueryClientProvider client={queryClient}>
      <LazyReactQueryGrid />
    </QueryClientProvider>
  );
}
